-c "#!/bin/bash
set -u
KEYS=\"${1:-}\"; SOURCES=\"${2:-}\"; BASE=\"${3:-}\"
if [[ -z \"${KEYS//[[:space:];]/}\" ]]; then
    echo \"DLCs: none configured. Skipping\"
    exit 0
fi
command -v python3 >/dev/null 2>&1 || { echo \"ERROR: DLC download preparation needs python3, which was not found.\"; exit 1; }
exec python3 -I - \"$KEYS\" \"$SOURCES\" \"$BASE\" <<'AMPDLC'
import hashlib, http.cookiejar, json, os, pathlib, re, shutil, signal, sys, tempfile, time
import urllib.error, urllib.parse, urllib.request

PORTAL = 'https://eshop.giants-software.com/downloads.php'
DOWNLOAD = 'https://eshop.giants-software.com/download.php'
UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'

class DLCError(Exception):
    pass

def parse_entries(keys_text, sources_text):
    keys, sources = {}, {}
    for raw in keys_text.replace(chr(10), ';').replace(chr(13), ';').split(';'):
        if not raw.strip():
            continue
        alias, sep, value = raw.partition('=')
        alias, value = alias.strip().lower(), ''.join(value.split()).upper()
        if not sep or not re.fullmatch('[a-z][a-z0-9_-]{0,47}', alias):
            raise DLCError('Invalid DLC key entry; use NAME=KEY, one per line or separated by semicolons.')
        if alias in keys:
            raise DLCError('Duplicate DLC key name: ' + alias)
        if not re.fullmatch('[A-Z0-9-]{10,80}', value):
            raise DLCError('Invalid product key format for ' + alias)
        keys[alias] = value
    for raw in sources_text.replace(chr(13), chr(10)).split(chr(10)):
        if not raw.strip():
            continue
        alias, sep, value = raw.partition('=')
        alias, value = alias.strip().lower(), value.strip()
        if not sep or alias not in keys or not value:
            raise DLCError('Every source needs NAME=SOURCE and a matching DLC key name.')
        if alias in sources:
            raise DLCError('Duplicate DLC source name: ' + alias)
        if any(ord(c) < 32 for c in value):
            raise DLCError('Invalid control character in source for ' + alias)
        sources[alias] = value
    return keys, sources

def fingerprint(keys, sources):
    data = json.dumps([keys, sources], sort_keys=True).encode()
    return hashlib.sha256(data).hexdigest()

def digest(path):
    h = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1048576), b''):
            h.update(chunk)
    return h.hexdigest()

def https_url(value):
    p = urllib.parse.urlsplit(value)
    if p.scheme != 'https' or not p.hostname or p.username or p.password or p.fragment:
        raise DLCError('A download source must be a direct HTTPS URL without credentials or a fragment.')
    return p

def kind(path):
    with path.open('rb') as stream:
        header = stream.read(64)
        if header[:2] == b'MZ' and len(header) == 64:
            offset = int.from_bytes(header[60:64], 'little')
            if 64 <= offset <= path.stat().st_size - 4:
                stream.seek(offset)
                if stream.read(4) == bytes((80, 69, 0, 0)):
                    return '.exe'
        stream.seek(32768)
        descriptors = stream.read(2048 * 48)
        if any(descriptors[i + 1:i + 6] in (b'CD001', b'NSR02', b'NSR03') for i in range(0, len(descriptors), 2048)):
            return '.img'
    raise DLCError('The source is not a Windows PE installer or a supported ISO9660/UDF image.')

def text_of(fragment):
    return re.sub('[ ]+', ' ', re.sub('<[^>]*>', ' ', fragment)).strip()

def portal_downloads(key):
    # Same flow as the base-game stage: post the key with a session cookie,
    # read the downloadId of each Windows row, then post it to the download page.
    jar = http.cookiejar.CookieJar()
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar))
    data = urllib.parse.urlencode({'activationKey': key}).encode()
    req = urllib.request.Request(PORTAL, data=data, headers={'User-Agent': UA})
    try:
        with opener.open(req, timeout=45) as response:
            final = https_url(response.url)
            if final.hostname.lower() != 'giants-software.com' and not final.hostname.lower().endswith('.giants-software.com'):
                raise DLCError('The GIANTS portal redirected to an unexpected host.')
            body = response.read(4194305)
    except (urllib.error.URLError, OSError):
        raise DLCError('Could not reach the GIANTS download portal.') from None
    if len(body) > 4194304:
        raise DLCError('The GIANTS portal returned an unexpectedly large page.')
    page = body.decode('utf-8', errors='replace')
    rows = {}
    for row in page.split('<tr')[1:]:
        if 'fa-windows' not in row:
            continue
        ident = re.search('name=.downloadId. value=.([0-9]+).', row)
        title = re.search('download-table-description.>(.*?)</', row, re.S)
        if not ident or not title:
            continue
        name = text_of(title.group(1))
        if not name or name == 'Farming Simulator 25':
            continue
        size = re.search('download-table-size.>([^<]+)', row)
        size = size.group(1).replace(' ', '') if size else '0'
        fmt = 'exe' if re.search('>[ ]*EXE[ ]*<', row) else 'img' if re.search('>[ ]*IMG[ ]*<', row) else ''
        if not fmt:
            continue
        # One installer per DLC: prefer the EXE over the IMG of the same package.
        if name not in rows or (fmt == 'exe' and rows[name]['format'] != 'exe'):
            rows[name] = {'name': name, 'id': ident.group(1), 'size': size, 'format': fmt}
    if not rows:
        if re.search('name=.activationKey. type=.text.', page):
            raise DLCError('The download portal did not accept that DLC product key.')
        raise DLCError('The portal returned no Windows FS25 DLC installer for that key; set a source override.')
    return opener, [rows[n] for n in sorted(rows)]

def fetch(opener, req, target):
    try:
        response = opener.open(req, timeout=60)
    except urllib.error.HTTPError as error:
        if error.code == 304:
            return False, None
        raise DLCError('DLC download failed (HTTP ' + str(error.code) + '); refresh or remove its source override.') from None
    except (urllib.error.URLError, OSError):
        raise DLCError('DLC download failed; check connectivity.') from None
    with response:
        https_url(response.url)
        length = int(response.headers.get('Content-Length') or 0)
        if length and shutil.disk_usage(target.parent).free < length + 536870912:
            raise DLCError('Not enough free space for the DLC download.')
        downloaded, deadline = 0, time.monotonic() + 7200
        with target.open('wb') as output:
            while True:
                if time.monotonic() > deadline:
                    raise DLCError('DLC download exceeded two hours.')
                block = response.read(1048576)
                if not block:
                    break
                if shutil.disk_usage(target.parent).free < len(block) + 67108864:
                    raise DLCError('Not enough free space to complete the DLC download.')
                output.write(block)
                downloaded += len(block)
        if length and downloaded != length:
            raise DLCError('The DLC download is incomplete.')
        return True, response.headers

def uploaded_file(inbox, source):
    relative = pathlib.PurePosixPath(source.replace(chr(92), '/'))
    if relative.is_absolute() or '..' in relative.parts or ':' in source:
        raise DLCError('Uploaded sources must be relative to this instance dlc-installers folder.')
    path = (inbox / relative).resolve()
    if inbox.resolve() not in path.parents or not path.is_file():
        raise DLCError('Uploaded DLC installer is missing or outside the upload folder.')
    return path

def cached_job(old, alias, identity, work):
    previous = next((j for j in old.get('jobs', []) if j.get('alias') == alias and j.get('source_id') == identity), {})
    name, checksum = previous.get('installer', ''), previous.get('sha256', '')
    if not re.fullmatch('[a-f0-9]{64}[.](exe|img)', name) or not name.startswith(checksum + '.'):
        return {}, None
    cached = work / name
    if cached.is_symlink() or not cached.is_file() or digest(cached) != checksum:
        return {}, None
    return previous, cached

def prepare(base, keys, sources):
    work, inbox = base / 'work' / 'dlc', base / 'dlc-installers'
    work.mkdir(parents=True, exist_ok=True)
    inbox.mkdir(parents=True, exist_ok=True)
    old = {}
    try:
        old = json.loads((work / 'pending.json').read_text())
    except (OSError, ValueError):
        pass
    jobs, seen = [], set()
    for alias, key in keys.items():
        print('DLC ' + alias + ': checking installation sources.', flush=True)
        source = sources.get(alias)
        items, opener = [], urllib.request.build_opener()
        if not source:
            opener, found = portal_downloads(key)
            for entry in found:
                identity = 'giants-' + entry['id'] + '-' + entry['size'] + '.' + entry['format']
                items.append(('portal', entry, identity))
        elif source.lower().startswith('https://'):
            https_url(source)
            items.append(('url', source, hashlib.sha256(source.encode()).hexdigest()))
        else:
            items.append(('upload', source, hashlib.sha256(source.encode()).hexdigest()))
        for mode, item, identity in items:
            previous, cached = cached_job(old, alias, identity, work)
            fd, name = tempfile.mkstemp(prefix=alias + '-', suffix='.part', dir=work)
            os.close(fd)
            temporary = pathlib.Path(name)
            try:
                metadata = {'source_id': identity}
                if mode == 'upload':
                    path = uploaded_file(inbox, item)
                elif mode == 'portal' and cached:
                    print('DLC ' + alias + ': ' + item['name'] + ' already downloaded.', flush=True)
                    path = cached
                else:
                    if mode == 'portal':
                        print('DLC ' + alias + ': downloading ' + item['name'] + ' (' + item['size'] + ').', flush=True)
                        data = urllib.parse.urlencode({'activationKey': key, 'downloadId': item['id']}).encode()
                        req = urllib.request.Request(DOWNLOAD, data=data, headers={'User-Agent': UA, 'Referer': PORTAL})
                    else:
                        headers = {'User-Agent': UA, 'Referer': PORTAL}
                        if cached:
                            for header, field in (('If-None-Match', 'etag'), ('If-Modified-Since', 'last_modified')):
                                if previous.get(field):
                                    headers[header] = previous[field]
                        req = urllib.request.Request(item, headers=headers)
                    changed, response_headers = fetch(opener, req, temporary)
                    if not changed:
                        if not cached:
                            raise DLCError('The DLC server reported no change but nothing is cached; run Update again.')
                        path, metadata = cached, previous
                    else:
                        path = temporary
                        if mode == 'url':
                            metadata = {'source_id': identity, 'etag': response_headers.get('ETag'), 'last_modified': response_headers.get('Last-Modified')}
                        elif path.stat().st_size < 1048576:
                            raise DLCError('GIANTS answered with a page instead of the DLC installer for ' + alias + '.')
                suffix, checksum = kind(path), digest(path)
                if checksum in seen:
                    print('DLC ' + alias + ': identical installer already queued; skipping duplicate.', flush=True)
                    continue
                destination = work / (checksum + suffix)
                if destination.is_symlink():
                    raise DLCError('The DLC installer cache contains an unexpected link.')
                if path != destination and (not destination.exists() or digest(destination) != checksum):
                    if path == temporary:
                        os.replace(path, destination)
                    else:
                        shutil.copyfile(path, temporary)
                        os.replace(temporary, destination)
                if digest(destination) != checksum:
                    raise DLCError('Cached DLC installer failed its checksum check.')
                seen.add(checksum)
                jobs.append(dict(metadata, alias=alias, installer=destination.name, sha256=checksum))
            finally:
                temporary.unlink(missing_ok=True)
    result = {'schema': 1, 'configuration': fingerprint(keys, sources), 'aliases': sorted(keys), 'jobs': jobs}
    temporary = work / 'pending.json.part'
    temporary.write_text(json.dumps(result, indent=2), encoding='utf-8')
    os.replace(temporary, work / 'pending.json')
    print('DLC download preparation complete: ' + str(len(jobs)) + ' installer(s).', flush=True)

def main():
    if len(sys.argv) != 4:
        raise DLCError('Invalid DLC preparation arguments.')
    keys, sources = parse_entries(sys.argv[1], sys.argv[2])
    base = pathlib.Path(sys.argv[3]).resolve()
    if not keys:
        print('DLCs: none configured.')
        return
    work = base / 'work' / 'dlc'
    work.mkdir(parents=True, exist_ok=True)
    import fcntl
    with (work / 'operation.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        prepare(base, keys, sources)

if __name__ == '__main__':
    def interrupted(signum, frame):
        raise KeyboardInterrupt
    signal.signal(signal.SIGTERM, interrupted)
    try:
        main()
    except KeyboardInterrupt:
        print('ERROR: DLC preparation interrupted; the previous pending manifest was retained.', file=sys.stderr)
        sys.exit(130)
    except DLCError as error:
        print('ERROR: ' + str(error), file=sys.stderr)
        sys.exit(1)
    except Exception:
        print('ERROR: DLC preparation failed; check connectivity, disk space, permissions and exclusive instance access. Existing pending data was retained.', file=sys.stderr)
        sys.exit(1)
AMPDLC
" fs-dlc-prepare "{{DLCProductKeysList}}" "{{DLCInstallSources}}" "{{$FullBaseDir}}"
